import json, requests, os
data = json.loads(exec_input)
wazuh_base = os.environ.get('WAZUH_API_URL', 'https://localhost:55000')
token_resp = requests.post(f'{wazuh_base}/security/user/authenticate', auth=('admin', os.environ.get('WAZUH_PASSWORD', 'WazuhAdmin@SOC2024')), verify=False)
token = token_resp.json().get('data', {}).get('token', '')
headers = {'Authorization': f'Bearer {token}'}
# Disable user account via active response
ar_payload = {'command': 'disable-account', 'arguments': [data['username']], 'alert': {'data': {'win': {'eventdata': {'targetUserName': data['username']}}}}}
ar_resp = requests.put(f'{wazuh_base}/active-response', headers=headers, json=ar_payload, verify=False)
return json.dumps({'action': 'isolated', 'agent': data['agent_name'], 'user': data['username'], 'ar_status': ar_resp.status_code})
